WITH src AS (SELECT *, ROUND(budget, 2) AS budget_rounded FROM departments WHERE dept_name <> 'Legal' AND dept_name NOT IN ('Finance', 'HR', 'Marketing')), budget_rounded_bucket_summary AS (SELECT CASE WHEN budget_rounded >= 81 THEN 'high' WHEN budget_rounded >= 16 THEN 'mid' ELSE 'low' END AS budget_rounded_bucket, location, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) AS dept_name_values, MAX(budget) AS max_budget FROM src GROUP BY CASE WHEN budget_rounded >= 81 THEN 'high' WHEN budget_rounded >= 16 THEN 'mid' ELSE 'low' END, location) SELECT * FROM budget_rounded_bucket_summary WHERE max_budget < 2239000 ORDER BY dept_name_values DESC, budget_rounded_bucket, location LIMIT 10;
